/*
 * Focused harness for the patched grub_mdraid_detect().
 *
 * This translation unit #includes the real target source
 * (grub-core/disk/mdraid1x_linux.c) so the guard logic under test is the
 * actual code from the candidate, compiled with the target's generated
 * config headers. GRUB runtime dependencies are stubbed so the static
 * function can be exercised directly with synthetic superblocks.
 */

#include <string.h>
#include <stdlib.h>
#include <stdarg.h>
#include <stdio.h>

#include "disk/mdraid1x_linux.c"

/* ---- synthetic device state ---- */
static struct grub_raid_super_1x g_sb;
static grub_uint64_t g_size;
static int g_make_raid_called;
static grub_uint64_t g_start_sector;

grub_err_t grub_errno;
char grub_errmsg[GRUB_MAX_ERRMSG];

grub_uint64_t
grub_disk_native_sectors (grub_disk_t disk)
{
  (void) disk;
  return g_size;
}

grub_err_t
grub_disk_read (grub_disk_t disk, grub_disk_addr_t sector, grub_off_t offset,
		grub_size_t size, void *buf)
{
  (void) disk;
  (void) sector;
  if (offset == 0)
    memcpy (buf, &g_sb, size);
  else
    {
      memset (buf, 0, size);
      if (size >= 2)
	*(grub_uint16_t *) buf = 0;	/* valid role 0 */
    }
  return 0;
}

struct grub_diskfilter_vg *
grub_diskfilter_make_raid (grub_size_t uuidlen, char *uuid, int nmemb,
			   const char *name, grub_uint64_t disk_size,
			   grub_uint64_t stripe_size, int layout, int level)
{
  (void) uuidlen; (void) uuid; (void) nmemb; (void) name;
  (void) disk_size; (void) stripe_size; (void) layout; (void) level;
  g_make_raid_called = 1;
  return (struct grub_diskfilter_vg *) (grub_addr_t) 0x1234;
}

void
grub_list_push (grub_list_t *head, grub_list_t item)
{
  (void) head; (void) item;
}

void
grub_list_remove (grub_list_t item)
{
  (void) item;
}

grub_err_t
grub_error (grub_err_t n, const char *file, const int line, const char *fmt, ...)
{
  (void) file; (void) line; (void) fmt;
  grub_errno = n;
  return n;
}

void *
grub_malloc (grub_size_t size)
{
  return malloc (size);
}

void *
grub_memmove (void *dest, const void *src, grub_size_t n)
{
  return memmove (dest, src, n);
}

void
grub_real_dprintf (const char *file, const int line, const char *condition,
		   const char *fmt, ...)
{
  (void) file; (void) line; (void) condition; (void) fmt;
}

grub_diskfilter_t grub_diskfilter_list;

/* ---- test driver ---- */
static void
reset_sb (void)
{
  memset (&g_sb, 0, sizeof (g_sb));
  g_sb.magic = 0xa92b4efc;			/* SB_MAGIC */
  g_sb.major_version = 1;
  g_sb.level = 1;
  g_sb.max_dev = 8;
  g_sb.dev_number = 0;
  g_sb.raid_disks = 2;
  g_make_raid_called = 0;
}

struct testcase
{
  const char *name;
  grub_uint8_t want_minor;
  grub_uint32_t raid_disks;
  grub_uint64_t data_offset;
  grub_uint64_t data_size;
  grub_uint64_t size;
  int want_accept;
};

static grub_disk_addr_t
sector_for (grub_uint8_t minor, grub_uint64_t size)
{
  switch (minor)
    {
    case 0:
      return (size - 8 * 2) & ~(4 * 2 - 1);
    case 1:
      return 0;
    default:
      return 4 * 2;
    }
}

static int
run_case (const struct testcase *t)
{
  struct grub_diskfilter_pv_id id;
  grub_disk_addr_t start = 0;
  struct grub_diskfilter_vg *res;

  reset_sb ();
  g_size = t->size;
  g_sb.raid_disks = t->raid_disks;
  g_sb.data_offset = t->data_offset;
  g_sb.data_size = t->data_size;
  g_sb.super_offset = sector_for (t->want_minor, t->size);

  memset (&id, 0, sizeof (id));
  res = grub_mdraid_detect ((grub_disk_t) 0, &id, &start);
  g_start_sector = start;

  int accepted = (res != NULL);
  int ok = (accepted == t->want_accept);
  printf ("%s  %-46s -> %s (make_raid=%d)\n", ok ? "PASS" : "FAIL", t->name,
	  accepted ? "accept" : "reject", g_make_raid_called);
  return ok;
}

int
main (void)
{
  struct testcase cases[] = {
    /* positive: well-formed minor 1 and minor 0 arrays must be accepted */
    {"minor1 well-formed",            1, 2, 2048, 100, 100000, 1},
    {"minor0 well-formed",            0, 2, 0,    100, 100000, 1},
    /* negatives: each guard must reject */
    {"data_size < 10",                1, 2, 2048, 5,   100000, 0},
    {"raid_disks > MAX (4096)",       1, 5000, 2048, 100, 100000, 0},
    {"data_end overflow",             1, 2, 0xffffffffffffffffULL, 100, 100000, 0},
    {"superblock/data overlap minor1",1, 2, 0,    100, 100000, 0},
    {"data past end of disk minor1",  1, 2, 2048, 200000, 100000, 0},
    {"superblock/data overlap minor0",0, 2, 0,    200000, 100000, 0},
    {"sb_end past end minor0",        0, 4096, 0, 100, 100000, 0},
    {"sb_end overflow minor0",        0, 4096, 0, 100, 0xffffffffffffffffULL, 0},
  };
  int total = (int) (sizeof (cases) / sizeof (cases[0]));
  int passed = 0;

  printf ("cases: %d\n", total);
  for (int i = 0; i < total; i++)
    passed += run_case (&cases[i]);

  printf ("result: %d/%d passed\n", passed, total);
  return (passed == total) ? 0 : 1;
}

